<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use GuzzleHttp\ClientInterface;
use GuzzleHttp\Psr7\Response;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider\MicrosoftOAuthProvider;

#[AllowMockObjectsWithoutExpectations]
final class MicrosoftOAuthProviderUnitTest extends TestCase
{
    public function testDelegatedUrlContainsTenant(): void
    {
        $provider = $this->createProvider($this->createMock(ClientInterface::class));
        $endpoint = $provider->delegeatedUrl('https://app.local/delegate/callback', 'state-123');

        $this->assertStringContainsString('/contoso-tenant/oauth2/v2.0/authorize', $endpoint->url);
        $this->assertStringContainsString('scope=openid+email+profile+User.Read', $endpoint->url);
    }

    public function testAuthorizeParsesIdToken(): void
    {
        $jwt = $this->fakeJwt([
            'sub' => 'ms-1',
            'email' => 'ms@example.com',
            'name' => 'MS User',
            'given_name' => 'MS',
            'family_name' => 'User',
        ]);

        $http = $this->createMock(ClientInterface::class);
        $http->method('request')->willReturn(new Response(200, [], '{"id_token":"' . $jwt . '"}'));

        $provider = $this->createProvider($http);
        $user = $provider->authorize('https://app.local/delegate/callback', ['code' => 'oauth-code']);

        $this->assertNotNull($user);
        $this->assertEquals('ms-1', $user->providerUserId);
        $this->assertEquals('ms@example.com', $user->email);
        $this->assertEquals('MS User', $user->name);
    }

    private function createProvider(ClientInterface $http): MicrosoftOAuthProvider
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://assets.local');

        $context = $this->createMock(Context::class);
        $context->method('getBaseUrl')->willReturn('https://app.local');

        return new MicrosoftOAuthProvider($config, $context, 'ms-provider', 'id', 'secret', 'contoso-tenant', $http);
    }

    private function fakeJwt(array $payload): string
    {
        $header = rtrim(strtr(base64_encode('{"alg":"none","typ":"JWT"}'), '+/', '-_'), '=');
        $body = rtrim(strtr(base64_encode((string) json_encode($payload)), '+/', '-_'), '=');
        return $header . '.' . $body . '.sig';
    }
}
